import {randomUUID} from 'node:crypto';
import {join} from 'node:path';
import {inputFixture} from './input-data.mjs';
import {LocalWorkbenchDirectories,AssistantWorkspaces} from '../../packages/code-workspaces/dist/index.mjs';
import {ConversationRuntime,providerConfigSchema} from '../../packages/agent-runtime/dist/index.mjs';
export const owner='user_1',meta=scopeId=>({principalId:owner,scopeId,idempotencyKey:randomUUID()}),post=(body,key=randomUUID())=>({method:'POST',headers:{'content-type':'application/json','idempotency-key':key},body:JSON.stringify(body)});
export const html='<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><title>英语学习</title><style>body{font-family:sans-serif;padding:2rem}button{padding:12px}</style></head><body><h1>英语学习网站</h1><button id="practice">开始练习</button><p id="result">准备好了</p><script>document.getElementById("practice").onclick=()=>document.getElementById("result").textContent="apple 的意思是苹果";</script></body></html>';
export const response=(content='',calls=[])=>({content,toolCalls:calls.map(([name,args])=>({id:'call_'+randomUUID(),name,arguments:JSON.stringify(args)})),finishReason:calls.length?'tool_calls':'stop',requestId:randomUUID(),usage:{inputTokens:30,outputTokens:30,source:'provider'},model:'fixture',cost:null});
export const decision=(action='DEVELOP',planOnly=false)=>response(JSON.stringify({reply:'我会生成英语学习网站。',intent:action==='INVESTIGATE'?'ANALYZE':'DEVELOP',action,goal:'生成英语学习网站HTML',planOnly,answers:[]}));
export function model(complete){return {config:providerConfigSchema.parse({providerId:'generated.fixture',model:'fixture',endpoint:'http://127.0.0.1:1',credentialRef:'fixture.key',capabilities:{revision:'v1',contextTokens:262144,maxOutputTokens:4096,toolCalls:true,structuredOutput:'json-object',tokenCounting:'utf8-conservative-v1',reasoningMode:'disabled',verification:'DECLARED'}}),complete};}
export function generator(){let n=0;return model(async r=>{if(!r.tools.length)return decision();n++;if(n===1)return response('',[['project_write',{path:'index.html',expectedSha256:null,text:html}]]);if(n===2)return response('',[['project_check',{check:'html'}]]);return response('英语学习网站已生成，可以预览或下载。');});}
export async function generatedFixture(t,provider=generator(),options={}){const proxy={};let runtime;const f=await inputFixture(t,{assistant:proxy,conversations:{capabilities:()=>runtime.capabilities(),control:(...args)=>runtime.control(...args)},...options});const directories=new LocalWorkbenchDirectories(f.storage,[f.root]),backend=new AssistantWorkspaces(join(f.root,'generated-workspaces'),directories);for(const name of ['capabilities','prepare','execute','query','recover','result','applicationPlan','apply','artifact'])proxy[name]=backend[name].bind(backend);runtime=new ConversationRuntime(f.storage,f.content,{baseline:{version:'1.0.0',baseCommit:'b'.repeat(40)},provider:()=>provider,preparation:()=>false,execution:()=>false,assistant:backend,progress:update=>f.api.publishConversationProgress(update),repositoryContext:async(p,id)=>({binding:(await f.storage.request('getConversationSpaceContext',{principalId:p,conversationId:id})).binding}),tokenLimit:900000});t.after(()=>runtime.stop());const id=(await f.call('/conversations',post({clientConversationId:randomUUID()}))).body.result.conversationId;const input=(text='创建一个英语学习网站html',executionMode='EXECUTE')=>f.call('/conversations/'+id+'/messages',post({text,executionMode,clientMessageId:randomUUID(),attachmentIds:[]})),view=()=>f.storage.request('getConversation',{principalId:owner,conversationId:id}),runTurn=async()=>{const turn=await f.storage.request('claimConversationTurn',{workerId:'generated.fixture'});if(!turn)throw Error('No queued turn');await runtime.process(turn,new AbortController().signal);return turn;};return {...f,id,input,view,runTurn,runtime,backend,directories};}
